insert into public.handbook_chapters (id, slug, part, part_title, title, summary, minutes, body_md, sources, blocks) values
(1, 'safety-first', 'A', 'Foundations', 'Safe to start', 'Who can start today, who should see a doctor first, and the signs that mean stop.', 3, 'Most adults can start exercising today. A small group should speak to a doctor first, and everyone should know the few signs that mean stop. Should you see a doctor first? Do you have chest pain, fainting, unusual breathlessness, a racing heartbeat or ankle swelling? Stop here. See a doctor before exercising. Go to the next question. Has a doctor told you that you have heart, kidney or metabolic disease such as diabetes? Get medical clearance first, then start light and build slowly. Go to the next question. Are you mostly inactive right now, exercising fewer than 3 days a week? Start at light to moderate effort and build up over weeks. Carry on, and build intensity gradually. Screening rests on three things: how active you are now, any signs or known disease, and how hard you plan to train. Normal during training Muscles burning near the end of a set Breathing hard, then recovering within a minute or two Muscle soreness a day or two later Stop and get help Chest pain, pressure or tightness Dizziness, faintness or confusion A heartbeat that feels irregular or racing Sharp or sudden joint pain Some  activity is better than none, even if you cannot reach the target yet Start low  and build slowly if you have been inactive Pregnant, recovering from surgery, or managing a long-term condition? Follow your doctor''s advice first. Levlofit will ask you and adjust.', array['Riebe D et al. Updating ACSM''s recommendations for exercise preparticipation health screening. Med Sci Sports Exerc 2015;47(11):2473-2479.', 'Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.']::text[], '{"sources": {"riebe2015": "Riebe D et al. Updating ACSM''s recommendations for exercise preparticipation health screening. Med Sci Sports Exerc 2015;47(11):2473-2479.", "who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462."}, "blocks": [{"t": "lead", "text": "Most adults can start exercising today. A small group should speak to a doctor first, and everyone should know the few signs that mean stop."}, {"t": "flow", "title": "Should you see a doctor first?", "items": [{"q": "Do you have chest pain, fainting, unusual breathlessness, a racing heartbeat or ankle swelling?", "yes": "Stop here. See a doctor before exercising.", "no": "Go to the next question."}, {"q": "Has a doctor told you that you have heart, kidney or metabolic disease such as diabetes?", "yes": "Get medical clearance first, then start light and build slowly.", "no": "Go to the next question."}, {"q": "Are you mostly inactive right now, exercising fewer than 3 days a week?", "yes": "Start at light to moderate effort and build up over weeks.", "no": "Carry on, and build intensity gradually."}], "note": "Screening rests on three things: how active you are now, any signs or known disease, and how hard you plan to train.", "source": "riebe2015"}, {"t": "compare", "do": {"title": "Normal during training", "items": ["Muscles burning near the end of a set", "Breathing hard, then recovering within a minute or two", "Muscle soreness a day or two later"]}, "dont": {"title": "Stop and get help", "items": ["Chest pain, pressure or tightness", "Dizziness, faintness or confusion", "A heartbeat that feels irregular or racing", "Sharp or sudden joint pain"]}}, {"t": "stats", "items": [{"value": "Some", "unit": "", "label": "activity is better than none, even if you cannot reach the target yet", "source": "who2020"}, {"value": "Start low", "unit": "", "label": "and build slowly if you have been inactive", "source": "who2020"}]}, {"t": "rule", "text": "Pregnant, recovering from surgery, or managing a long-term condition? Follow your doctor''s advice first. Levlofit will ask you and adjust."}]}'::jsonb),
(2, 'how-training-works', 'A', 'Foundations', 'How training works', 'Stress, recover, adapt: why you get fitter, and the weekly amounts that improve health.', 4, 'Training is a signal. You stress the body a little more than it is used to, it recovers, and it rebuilds to handle that stress next time. The adaptation loop Train Tire Recover Adapt Do a little more Four rules behind every plan Specific You get better at what you practise. Running builds running, lifting builds strength. Progressive Add a little over time: a rep, a set, a kilo or a minute. Recovered Adaptation happens between sessions, not during them. Consistent Months of regular training beat any single perfect week. Weekly aerobic activity for adults minutes a week Moderate, at least 150 min Moderate, for more benefit 300 min Or vigorous, at least 75 min Or vigorous, for more benefit 150 min 2 days a week of muscle strengthening for all major muscles Less sitting and more movement in its place benefits health at any fitness level The ACSM 2026 review of 137 systematic reviews found the biggest gains come from going from no resistance training to any resistance training. Details matter less than doing it regularly. strong', array['Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.', 'Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"who2020": "Bull FC et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54:1451-1462.", "acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "Training is a signal. You stress the body a little more than it is used to, it recovers, and it rebuilds to handle that stress next time."}, {"t": "cycle", "title": "The adaptation loop", "items": ["Train", "Tire", "Recover", "Adapt", "Do a little more"]}, {"t": "steps", "title": "Four rules behind every plan", "items": [{"title": "Specific", "text": "You get better at what you practise. Running builds running, lifting builds strength."}, {"title": "Progressive", "text": "Add a little over time: a rep, a set, a kilo or a minute."}, {"title": "Recovered", "text": "Adaptation happens between sessions, not during them."}, {"title": "Consistent", "text": "Months of regular training beat any single perfect week."}]}, {"t": "bars", "title": "Weekly aerobic activity for adults", "unit": "minutes a week", "items": [{"label": "Moderate, at least", "value": 150, "note": "150 min"}, {"label": "Moderate, for more benefit", "value": 300, "note": "300 min"}, {"label": "Or vigorous, at least", "value": 75, "note": "75 min"}, {"label": "Or vigorous, for more benefit", "value": 150, "note": "150 min"}], "source": "who2020"}, {"t": "stats", "items": [{"value": "2", "unit": "days a week", "label": "of muscle strengthening for all major muscles", "source": "who2020"}, {"value": "Less", "unit": "sitting", "label": "and more movement in its place benefits health at any fitness level", "source": "who2020"}]}, {"t": "evidence", "text": "The ACSM 2026 review of 137 systematic reviews found the biggest gains come from going from no resistance training to any resistance training. Details matter less than doing it regularly.", "source": "acsm2026", "grade": "strong"}]}'::jsonb),
(3, 'effort-and-rir', 'A', 'Foundations', 'How hard to push', 'Reps in reserve: the simple scale Levlofit uses to set effort on every set.', 3, 'After a set, ask one question: how many more good reps could I have done? That number is your reps in reserve, or RIR. Reps in reserve scale 0 Failure No more reps possible with good form 1 Very hard One rep left 2 Hard Two reps left 3 Challenging Three reps left 4+ Moderate Four or more left 2 to 3 RIR is close enough to failure to build muscle 30 to 100 % of max all build muscle when sets end near failure Do End most working sets with 1 to 3 reps left Keep form identical on the last rep Leave an extra rep in hand while learning a lift Avoid Taking every set to total failure Grinding reps with form breaking down Trusting your RIR guess in the first week of a new lift Beginners are less accurate at judging reps in reserve than experienced lifters, and get better with practice. Start conservative. moderate', array['Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275.', 'Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.']::text[], '{"sources": {"zourdos2016": "Zourdos MC et al. Novel resistance training-specific rating of perceived exertion scale measuring repetitions in reserve. J Strength Cond Res 2016;30(1):267-275.", "acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026."}, "blocks": [{"t": "lead", "text": "After a set, ask one question: how many more good reps could I have done? That number is your reps in reserve, or RIR."}, {"t": "scale", "title": "Reps in reserve scale", "items": [{"mark": "0", "label": "Failure", "text": "No more reps possible with good form"}, {"mark": "1", "label": "Very hard", "text": "One rep left"}, {"mark": "2", "label": "Hard", "text": "Two reps left"}, {"mark": "3", "label": "Challenging", "text": "Three reps left"}, {"mark": "4+", "label": "Moderate", "text": "Four or more left"}], "source": "zourdos2016"}, {"t": "stats", "items": [{"value": "2 to 3", "unit": "RIR", "label": "is close enough to failure to build muscle", "source": "acsm2026"}, {"value": "30 to 100", "unit": "% of max", "label": "all build muscle when sets end near failure", "source": "acsm2026"}]}, {"t": "compare", "do": {"title": "Do", "items": ["End most working sets with 1 to 3 reps left", "Keep form identical on the last rep", "Leave an extra rep in hand while learning a lift"]}, "dont": {"title": "Avoid", "items": ["Taking every set to total failure", "Grinding reps with form breaking down", "Trusting your RIR guess in the first week of a new lift"]}}, {"t": "evidence", "text": "Beginners are less accurate at judging reps in reserve than experienced lifters, and get better with practice. Start conservative.", "source": "zourdos2016", "grade": "moderate"}]}'::jsonb),
(4, 'warm-up', 'A', 'Foundations', 'Warming up', 'A short warm-up that prepares you without draining strength.', 3, 'A good warm-up raises body temperature, moves the joints you are about to use, and rehearses the first exercise with light weight. A 10 minute warm-up Raise 3 to 5 minutes of easy movement: brisk walk, cycle or skipping. Mobilise Dynamic moves through full range: leg swings, arm circles, bodyweight squats. Rehearse 2 to 3 lighter sets of your first exercise, building up to your working weight. Before hard training Dynamic movements Light sets of the main lift Short static stretches if a sport needs the range Save for later Long static holds of 60 seconds or more per muscle Stretching so hard it hurts 60 seconds or more of static stretching per muscle can reduce strength and power for a short time Dynamic stretching has no negative effect and can help performance. Long static stretches cause a small, short-lived drop in force, so keep them after training. strong', array['Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11.', 'Warneke K et al. Revisiting the stretch-induced force deficit: a systematic review with multilevel meta-analysis of acute effects. J Sport Health Sci 2024.']::text[], '{"sources": {"behm2016": "Behm DG et al. Acute effects of muscle stretching on physical performance, range of motion, and injury incidence in healthy active individuals: a systematic review. Appl Physiol Nutr Metab 2016;41(1):1-11.", "warneke2024": "Warneke K et al. Revisiting the stretch-induced force deficit: a systematic review with multilevel meta-analysis of acute effects. J Sport Health Sci 2024."}, "blocks": [{"t": "lead", "text": "A good warm-up raises body temperature, moves the joints you are about to use, and rehearses the first exercise with light weight."}, {"t": "steps", "title": "A 10 minute warm-up", "items": [{"title": "Raise", "text": "3 to 5 minutes of easy movement: brisk walk, cycle or skipping."}, {"title": "Mobilise", "text": "Dynamic moves through full range: leg swings, arm circles, bodyweight squats."}, {"title": "Rehearse", "text": "2 to 3 lighter sets of your first exercise, building up to your working weight."}]}, {"t": "compare", "do": {"title": "Before hard training", "items": ["Dynamic movements", "Light sets of the main lift", "Short static stretches if a sport needs the range"]}, "dont": {"title": "Save for later", "items": ["Long static holds of 60 seconds or more per muscle", "Stretching so hard it hurts"]}}, {"t": "stats", "items": [{"value": "60", "unit": "seconds", "label": "or more of static stretching per muscle can reduce strength and power for a short time", "source": "behm2016"}]}, {"t": "evidence", "text": "Dynamic stretching has no negative effect and can help performance. Long static stretches cause a small, short-lived drop in force, so keep them after training.", "source": "warneke2024", "grade": "strong"}]}'::jsonb),
(5, 'sets-reps-progress', 'A', 'Foundations', 'Sets, reps and progress', 'How much to lift for strength or muscle, how to progress, and when to ease off.', 4, 'Pick the goal, then match the dose. Strength wants heavy sets, muscle wants enough hard sets, and both want slow, steady progress. Goal Load Volume Frequency Strength 80% of max or more 2 to 3 sets per lift 2 or more sessions a week Muscle size 30 to 100% of max, near failure 10 or more sets per muscle a week Each muscle 2 times a week General health Any challenging load All major muscles 2 or more days a week Double progression, the simplest way to progress Pick a rep range For example 8 to 12 reps. Add reps Stay at the same weight until every set reaches the top of the range. Add weight Increase the load a little and drop back to the bottom of the range. Repeat Small steps, every week or two. Example: 3 full-body days Mon Full body Tue Walk Wed Full body Thu Rest Fri Full body Sat Walk or sport Sun Rest 4 to 8 weeks between planned deloads is common practice 40 to 50 % less volume during a deload week Expert coaches agree a deload is a planned lighter period to shed fatigue and come back ready. It is not a week off. consensus', array['Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.', 'Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87.']::text[], '{"sources": {"acsm2026": "Currier BS, D''Souza AC, Fiatarone Singh MA et al. American College of Sports Medicine position stand: Resistance training prescription for muscle function, hypertrophy, and physical performance in healthy adults: an overview of reviews. Med Sci Sports Exerc 2026.", "bell2023": "Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87."}, "blocks": [{"t": "lead", "text": "Pick the goal, then match the dose. Strength wants heavy sets, muscle wants enough hard sets, and both want slow, steady progress."}, {"t": "table", "head": ["Goal", "Load", "Volume", "Frequency"], "rows": [["Strength", "80% of max or more", "2 to 3 sets per lift", "2 or more sessions a week"], ["Muscle size", "30 to 100% of max, near failure", "10 or more sets per muscle a week", "Each muscle 2 times a week"], ["General health", "Any challenging load", "All major muscles", "2 or more days a week"]], "source": "acsm2026"}, {"t": "steps", "title": "Double progression, the simplest way to progress", "items": [{"title": "Pick a rep range", "text": "For example 8 to 12 reps."}, {"title": "Add reps", "text": "Stay at the same weight until every set reaches the top of the range."}, {"title": "Add weight", "text": "Increase the load a little and drop back to the bottom of the range."}, {"title": "Repeat", "text": "Small steps, every week or two."}]}, {"t": "week", "title": "Example: 3 full-body days", "days": [{"day": "Mon", "label": "Full body", "kind": "strength"}, {"day": "Tue", "label": "Walk", "kind": "cardio"}, {"day": "Wed", "label": "Full body", "kind": "strength"}, {"day": "Thu", "label": "Rest", "kind": "rest"}, {"day": "Fri", "label": "Full body", "kind": "strength"}, {"day": "Sat", "label": "Walk or sport", "kind": "cardio"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "stats", "items": [{"value": "4 to 8", "unit": "weeks", "label": "between planned deloads is common practice", "source": "bell2023"}, {"value": "40 to 50", "unit": "% less volume", "label": "during a deload week", "source": "bell2023"}]}, {"t": "evidence", "text": "Expert coaches agree a deload is a planned lighter period to shed fatigue and come back ready. It is not a week off.", "source": "bell2023", "grade": "consensus"}]}'::jsonb),
(6, 'food-basics', 'A', 'Foundations', 'Food for training', 'The Indian plate, how much protein you need, and the best vegetarian and non-vegetarian sources.', 5, 'Build the plate first, then fix protein. Most Indian meals are rich in cereal and short on protein, so that is where training changes things. My Plate for the Day, per 2000 kcal Vegetables and greens 400 g Cereals and millets 250 g Fruits 100 g Pulses, eggs or meat 85 g Nuts and seeds 35 g Oils and fats 27 g Protein per kg of body weight, per day g per kg Inactive adult, Indian RDA 0.83 g Training adult, lower end 1.4 g Training adult, upper end 2.0 g 20 to 40 g protein per meal, spread every 3 to 4 hours 30 % or less of daily energy from fat 0.83 g per kg is the Indian RDA for a healthy, inactive adult Food, per 100 g raw Protein Energy Soya bean, white 37.8 g 377 kcal Masoor dal 24.4 g 322 kcal Moong, whole 22.5 g 294 kcal Chicken breast, skinless 21.8 g 168 kcal Rajma, red 19.9 g 299 kcal Paneer 18.9 g 258 kcal Kala chana 18.8 g 287 kcal Egg, whole 13.3 g 135 kcal Atta 10.6 g 320 kcal Cow milk 3.3 g 73 kcal Across 41 clinical studies, soy protein and isoflavones did not change testosterone or oestrogen in men, at any dose tested. Levlofit still caps soya chunks at 50 g dry a day, for variety rather than safety. strong', array['ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.', 'ICMR-National Institute of Nutrition. Nutrient Requirements for Indians (RDA and EAR), 2020.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.', 'Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.', 'Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67.']::text[], '{"sources": {"icmr2024": "ICMR-National Institute of Nutrition. Dietary Guidelines for Indians, 2024.", "icmr2020": "ICMR-National Institute of Nutrition. Nutrient Requirements for Indians (RDA and EAR), 2020.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.", "ifct2017": "Longvah T et al. Indian Food Composition Tables 2017. ICMR-National Institute of Nutrition, Hyderabad.", "soy2021": "Reed KE et al. Neither soy nor isoflavone intake affects male reproductive hormones: an expanded and updated meta-analysis of clinical studies. Reprod Toxicol 2021;100:60-67."}, "blocks": [{"t": "lead", "text": "Build the plate first, then fix protein. Most Indian meals are rich in cereal and short on protein, so that is where training changes things."}, {"t": "plate", "title": "My Plate for the Day, per 2000 kcal", "items": [{"label": "Vegetables and greens", "share": 400, "note": "400 g"}, {"label": "Cereals and millets", "share": 250, "note": "250 g"}, {"label": "Fruits", "share": 100, "note": "100 g"}, {"label": "Pulses, eggs or meat", "share": 85, "note": "85 g"}, {"label": "Nuts and seeds", "share": 35, "note": "35 g"}, {"label": "Oils and fats", "share": 27, "note": "27 g"}], "source": "icmr2024"}, {"t": "bars", "title": "Protein per kg of body weight, per day", "unit": "g per kg", "items": [{"label": "Inactive adult, Indian RDA", "value": 0.83, "note": "0.83 g"}, {"label": "Training adult, lower end", "value": 1.4, "note": "1.4 g"}, {"label": "Training adult, upper end", "value": 2.0, "note": "2.0 g"}], "source": "issnprotein"}, {"t": "stats", "items": [{"value": "20 to 40", "unit": "g", "label": "protein per meal, spread every 3 to 4 hours", "source": "issnprotein"}, {"value": "30", "unit": "% or less", "label": "of daily energy from fat", "source": "icmr2024"}, {"value": "0.83", "unit": "g per kg", "label": "is the Indian RDA for a healthy, inactive adult", "source": "icmr2020"}]}, {"t": "table", "head": ["Food, per 100 g raw", "Protein", "Energy"], "rows": [["Soya bean, white", "37.8 g", "377 kcal"], ["Masoor dal", "24.4 g", "322 kcal"], ["Moong, whole", "22.5 g", "294 kcal"], ["Chicken breast, skinless", "21.8 g", "168 kcal"], ["Rajma, red", "19.9 g", "299 kcal"], ["Paneer", "18.9 g", "258 kcal"], ["Kala chana", "18.8 g", "287 kcal"], ["Egg, whole", "13.3 g", "135 kcal"], ["Atta", "10.6 g", "320 kcal"], ["Cow milk", "3.3 g", "73 kcal"]], "source": "ifct2017"}, {"t": "evidence", "text": "Across 41 clinical studies, soy protein and isoflavones did not change testosterone or oestrogen in men, at any dose tested. Levlofit still caps soya chunks at 50 g dry a day, for variety rather than safety.", "source": "soy2021", "grade": "strong"}]}'::jsonb),
(7, 'water', 'A', 'Foundations', 'Water and sweat', 'How to tell if you are drinking enough in Indian heat, without guesswork.', 2, 'Start training well hydrated, and drink enough during long or hot sessions to avoid losing more than 2% of your body weight. 2 % of body weight lost as sweat is where performance starts to suffer Check your sweat loss Weigh before Light clothes, after using the toilet. Train Note how much you drink. Weigh after Towel off first. Compare A 70 kg person should lose under 1.4 kg. More than that? Drink more next time. Signs you are fine Pale yellow urine Body weight back to normal by the next morning Signs to drink more Dark urine, or very little of it Headache or dizziness after training Long sessions in heat lose salt as well as water. Salted food, lassi or chaas after training helps replace it.', array['Sawka MN et al. American College of Sports Medicine position stand: exercise and fluid replacement. Med Sci Sports Exerc 2007;39(2):377-390.']::text[], '{"sources": {"acsmfluid": "Sawka MN et al. American College of Sports Medicine position stand: exercise and fluid replacement. Med Sci Sports Exerc 2007;39(2):377-390."}, "blocks": [{"t": "lead", "text": "Start training well hydrated, and drink enough during long or hot sessions to avoid losing more than 2% of your body weight."}, {"t": "stats", "items": [{"value": "2", "unit": "% of body weight", "label": "lost as sweat is where performance starts to suffer", "source": "acsmfluid"}]}, {"t": "steps", "title": "Check your sweat loss", "items": [{"title": "Weigh before", "text": "Light clothes, after using the toilet."}, {"title": "Train", "text": "Note how much you drink."}, {"title": "Weigh after", "text": "Towel off first."}, {"title": "Compare", "text": "A 70 kg person should lose under 1.4 kg. More than that? Drink more next time."}]}, {"t": "compare", "do": {"title": "Signs you are fine", "items": ["Pale yellow urine", "Body weight back to normal by the next morning"]}, "dont": {"title": "Signs to drink more", "items": ["Dark urine, or very little of it", "Headache or dizziness after training"]}}, {"t": "rule", "text": "Long sessions in heat lose salt as well as water. Salted food, lassi or chaas after training helps replace it."}]}'::jsonb),
(8, 'body-measures', 'A', 'Foundations', 'Reading your body numbers', 'BMI cut-offs for Indians, why waist matters, and what the numbers cannot tell you.', 3, 'Asian Indians carry more health risk at a lower weight than Western cut-offs assume, so Levlofit uses Indian cut-offs and your waist. BMI for Asian Indians kg/m² Underweight Normal Overweight Obese Waist to height ratio ratio Healthy Increased risk High risk Measure your waist Find the spot Midway between your lowest rib and the top of your hip bone. Breathe out Relax, do not pull the belly in. Read Tape level and snug, not tight. Divide Waist in cm divided by height in cm. BMI is good for Quick screening Tracking change in the same person BMI misses Muscle versus fat Where fat is stored', array['Misra A et al. Consensus statement for diagnosis of obesity, abdominal obesity and the metabolic syndrome for Asian Indians. J Assoc Physicians India 2009;57:163-170.', 'National Institute for Health and Care Excellence. Obesity: identification, assessment and management (waist-to-height ratio update), 2022.']::text[], '{"sources": {"misra2009": "Misra A et al. Consensus statement for diagnosis of obesity, abdominal obesity and the metabolic syndrome for Asian Indians. J Assoc Physicians India 2009;57:163-170.", "nice2022": "National Institute for Health and Care Excellence. Obesity: identification, assessment and management (waist-to-height ratio update), 2022."}, "blocks": [{"t": "lead", "text": "Asian Indians carry more health risk at a lower weight than Western cut-offs assume, so Levlofit uses Indian cut-offs and your waist."}, {"t": "band", "title": "BMI for Asian Indians", "unit": "kg/m²", "ranges": [{"from": 14, "to": 18, "label": "Underweight", "tone": "warn"}, {"from": 18, "to": 23, "label": "Normal", "tone": "good"}, {"from": 23, "to": 25, "label": "Overweight", "tone": "warn"}, {"from": 25, "to": 35, "label": "Obese", "tone": "bad"}], "source": "misra2009"}, {"t": "band", "title": "Waist to height ratio", "unit": "ratio", "ranges": [{"from": 0.3, "to": 0.5, "label": "Healthy", "tone": "good"}, {"from": 0.5, "to": 0.6, "label": "Increased risk", "tone": "warn"}, {"from": 0.6, "to": 0.8, "label": "High risk", "tone": "bad"}], "source": "nice2022"}, {"t": "steps", "title": "Measure your waist", "items": [{"title": "Find the spot", "text": "Midway between your lowest rib and the top of your hip bone."}, {"title": "Breathe out", "text": "Relax, do not pull the belly in."}, {"title": "Read", "text": "Tape level and snug, not tight."}, {"title": "Divide", "text": "Waist in cm divided by height in cm."}]}, {"t": "compare", "do": {"title": "BMI is good for", "items": ["Quick screening", "Tracking change in the same person"]}, "dont": {"title": "BMI misses", "items": ["Muscle versus fat", "Where fat is stored"]}}]}'::jsonb),
(9, 'sleep-recovery', 'A', 'Foundations', 'Sleep and recovery', 'Why sleep is part of training, and how to spot too much fatigue.', 3, 'You train in the gym and improve while you rest. Sleep is part of the plan, not time off from it. 7+ hours of sleep a night, regularly, for adults 18 to 60 Recovery in a week Hard session Easy day or rest Sleep 7+ hours Next hard session Recovering well Weights feel normal or lighter You look forward to training Sleep is steady Too much fatigue Performance drops for more than a week Motivation keeps falling Aches that do not settle Hard and easy days Mon Hard Tue Easy walk Wed Hard Thu Rest Fri Hard Sat Easy Sun Rest Coaches use planned lighter weeks, called deloads, to clear fatigue before it becomes a problem. consensus', array['Watson NF et al. Recommended amount of sleep for a healthy adult: a joint consensus statement of the AASM and SRS. J Clin Sleep Med 2015;11(6):591-592.', 'Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87.']::text[], '{"sources": {"aasm2015": "Watson NF et al. Recommended amount of sleep for a healthy adult: a joint consensus statement of the AASM and SRS. J Clin Sleep Med 2015;11(6):591-592.", "bell2023": "Bell L et al. Integrating deloading into strength and physique sports training programmes: an international Delphi consensus approach. Sports Med Open 2023;9:87."}, "blocks": [{"t": "lead", "text": "You train in the gym and improve while you rest. Sleep is part of the plan, not time off from it."}, {"t": "stats", "items": [{"value": "7+", "unit": "hours", "label": "of sleep a night, regularly, for adults 18 to 60", "source": "aasm2015"}]}, {"t": "cycle", "title": "Recovery in a week", "items": ["Hard session", "Easy day or rest", "Sleep 7+ hours", "Next hard session"]}, {"t": "compare", "do": {"title": "Recovering well", "items": ["Weights feel normal or lighter", "You look forward to training", "Sleep is steady"]}, "dont": {"title": "Too much fatigue", "items": ["Performance drops for more than a week", "Motivation keeps falling", "Aches that do not settle"]}}, {"t": "week", "title": "Hard and easy days", "days": [{"day": "Mon", "label": "Hard", "kind": "strength"}, {"day": "Tue", "label": "Easy walk", "kind": "cardio"}, {"day": "Wed", "label": "Hard", "kind": "strength"}, {"day": "Thu", "label": "Rest", "kind": "rest"}, {"day": "Fri", "label": "Hard", "kind": "strength"}, {"day": "Sat", "label": "Easy", "kind": "mobility"}, {"day": "Sun", "label": "Rest", "kind": "rest"}]}, {"t": "evidence", "text": "Coaches use planned lighter weeks, called deloads, to clear fatigue before it becomes a problem.", "source": "bell2023", "grade": "consensus"}]}'::jsonb),
(10, 'supplements', 'A', 'Foundations', 'Supplements that work', 'Creatine, caffeine and protein powder: doses, timing and what they really do.', 4, 'Food first. A few supplements have strong evidence and can help. None replaces training, sleep or enough protein from meals. Supplement Dose Timing Creatine monohydrate 3 to 5 g a day Any time, every day Caffeine 3 to 6 mg per kg About 60 min before Protein powder 20 to 40 g a serving When meals fall short 3 to 5 g a day of creatine keeps muscle stores full, no loading needed 0.3 g per kg a day for 5 to 7 days fills stores faster, if you choose to load 3 to 6 mg per kg of caffeine improves performance, about 60 minutes before 9 mg per kg of caffeine and above brings more side effects, with no extra benefit Caffeine for a 70 kg person mg Effective, low end (3 mg/kg) 210 mg Effective, high end (6 mg/kg) 420 mg More side effects (9 mg/kg) 630 mg Creatine has been studied for up to 5 years at doses up to 30 g a day in healthy people and was safe and well tolerated. Protein powder is simply protein: a serving counts the same as protein from food. strong Worth it Creatine monohydrate for strength and muscle Caffeine for performance, if it suits you Protein powder if food cannot reach your target Be careful Caffeine late in the day, it can cut sleep Any supplement with a health condition: ask a doctor first', array['Kreider RB et al. International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. J Int Soc Sports Nutr 2017;14:18.', 'Guest NS et al. International Society of Sports Nutrition position stand: caffeine and exercise performance. J Int Soc Sports Nutr 2021;18:1.', 'Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20.']::text[], '{"sources": {"issncreatine": "Kreider RB et al. International Society of Sports Nutrition position stand: safety and efficacy of creatine supplementation in exercise, sport, and medicine. J Int Soc Sports Nutr 2017;14:18.", "issncaffeine": "Guest NS et al. International Society of Sports Nutrition position stand: caffeine and exercise performance. J Int Soc Sports Nutr 2021;18:1.", "issnprotein": "Jager R et al. International Society of Sports Nutrition position stand: protein and exercise. J Int Soc Sports Nutr 2017;14:20."}, "blocks": [{"t": "lead", "text": "Food first. A few supplements have strong evidence and can help. None replaces training, sleep or enough protein from meals."}, {"t": "table", "head": ["Supplement", "Dose", "Timing"], "rows": [["Creatine monohydrate", "3 to 5 g a day", "Any time, every day"], ["Caffeine", "3 to 6 mg per kg", "About 60 min before"], ["Protein powder", "20 to 40 g a serving", "When meals fall short"]], "source": null}, {"t": "stats", "items": [{"value": "3 to 5", "unit": "g a day", "label": "of creatine keeps muscle stores full, no loading needed", "source": "issncreatine"}, {"value": "0.3", "unit": "g per kg", "label": "a day for 5 to 7 days fills stores faster, if you choose to load", "source": "issncreatine"}, {"value": "3 to 6", "unit": "mg per kg", "label": "of caffeine improves performance, about 60 minutes before", "source": "issncaffeine"}, {"value": "9", "unit": "mg per kg", "label": "of caffeine and above brings more side effects, with no extra benefit", "source": "issncaffeine"}]}, {"t": "bars", "title": "Caffeine for a 70 kg person", "unit": "mg", "items": [{"label": "Effective, low end (3 mg/kg)", "value": 210, "note": "210 mg"}, {"label": "Effective, high end (6 mg/kg)", "value": 420, "note": "420 mg"}, {"label": "More side effects (9 mg/kg)", "value": 630, "note": "630 mg"}], "source": "issncaffeine"}, {"t": "evidence", "text": "Creatine has been studied for up to 5 years at doses up to 30 g a day in healthy people and was safe and well tolerated. Protein powder is simply protein: a serving counts the same as protein from food.", "source": "issncreatine", "grade": "strong"}, {"t": "compare", "do": {"title": "Worth it", "items": ["Creatine monohydrate for strength and muscle", "Caffeine for performance, if it suits you", "Protein powder if food cannot reach your target"]}, "dont": {"title": "Be careful", "items": ["Caffeine late in the day, it can cut sleep", "Any supplement with a health condition: ask a doctor first"]}}]}'::jsonb);
